package com.pohteleportsorter;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.util.Collections;
import java.util.EnumMap;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;

/**
 * Custom hotkeys for the Portal Nexus and jewellery box teleports.
 *
 * Right-click a teleport and choose "Set hotkey", then press a key (a letter, number or symbol; Esc cancels).
 * "Reset hotkey" gives the teleport the game's key back.
 *
 * The plugin never presses or runs anything itself. Each teleport's hotkey is the game's own key listener, which
 * checks the typed character against the one or two characters it was given (upper and lower case). Setting a
 * hotkey just changes those characters: the game then handles the key press and the teleport exactly as it
 * always does. A teleport whose game key now belongs to another teleport is given no key at all.
 *
 * The only key this class ever takes is the one pressed while choosing a hotkey, so it can't also reach the game.
 * While Better Teleport Menu is on, all of this steps aside (see {@link BetterTeleportMenu}), and the game's
 * listeners are left exactly as they were.
 */
@Singleton
public class TeleportHotkeys implements KeyListener
{
	public enum Kind
	{
		NEXUS(PohTeleportSorterConfig.HOTKEYS_NEXUS),
		JEWELLERY(PohTeleportSorterConfig.HOTKEYS_JEWELLERY);

		private final String key;

		Kind(String key)
		{
			this.key = key;
		}
	}

	/** Shown in place of the key while waiting for the key to bind. */
	static final String PROMPT = "Press a key";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PinStore pins;

	@Inject
	private BetterTeleportMenu betterTeleportMenu;

	// The open window and how to redraw it after a hotkey changes
	private volatile Kind openKind;
	private volatile Runnable redraw;

	// Waiting for the key to bind to this teleport
	private volatile Kind captureKind;
	private volatile String captureName;

	// The key press that chose a hotkey: its typed and released events are consumed too
	private volatile boolean swallowTyped;

	// The game's own listeners as they were before this plugin changed them, so they can be put back exactly
	private final Map<Widget, Object[]> originalKeyListeners = new IdentityHashMap<>();
	private final Map<Widget, Object[]> originalOpListeners = new IdentityHashMap<>();

	/** Called on the client thread whenever a window lays its teleports out. */
	void setWindow(Kind kind, Runnable redrawWindow)
	{
		if (openKind != kind)
		{
			forgetListeners();
		}
		openKind = kind;
		redraw = redrawWindow;
	}

	/** Called when a window closes: its widgets are gone, so nothing needs putting back. */
	void clearWindow(Kind kind)
	{
		if (openKind == kind)
		{
			openKind = null;
			redraw = null;
			forgetListeners();
		}
		if (captureKind == kind)
		{
			captureKind = null;
			captureName = null;
		}
	}

	/** Forgets a window as soon as it's gone, however it closed. */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		Kind kind = openKind;
		if (kind != null && !isOpen(kind))
		{
			clearWindow(kind);
		}
	}

	/** Custom hotkeys work (and can be set) unless Better Teleport Menu is on. */
	boolean isEnabled()
	{
		return !betterTeleportMenu.isActive();
	}

	// ---------------------------------------------------------------- stored hotkeys

	// The last stored text read for each window and what it parsed to, so labels drawn every frame don't re-parse
	private final Map<Kind, String> cachedRaw = new EnumMap<>(Kind.class);
	private final Map<Kind, Map<String, Character>> cachedMap = new EnumMap<>(Kind.class);

	/** The custom hotkeys for a window, by teleport name (lower-case characters), in the order they were set. */
	synchronized Map<String, Character> view(Kind kind)
	{
		String raw = configManager.getConfiguration(PohTeleportSorterConfig.GROUP, kind.key);
		Map<String, Character> map = cachedMap.get(kind);
		if (map == null || !Objects.equals(raw, cachedRaw.get(kind)))
		{
			map = Collections.unmodifiableMap(parse(raw));
			cachedRaw.put(kind, raw);
			cachedMap.put(kind, map);
		}
		return map;
	}

	boolean hasAny(Kind kind)
	{
		return !view(kind).isEmpty();
	}

	private Map<String, Character> all(Kind kind)
	{
		return new LinkedHashMap<>(view(kind));
	}

	/**
	 * Reads the stored hotkeys: one "name, tab, character" per line. Lines saved by earlier test builds as "name,
	 * tab, key code, tab, modifiers" are read too where they were a plain letter or number; anything else is dropped.
	 */
	static Map<String, Character> parse(String raw)
	{
		Map<String, Character> out = new LinkedHashMap<>();
		if (raw == null)
		{
			return out;
		}
		for (String line : raw.split("\n"))
		{
			String[] parts = line.split("\t", -1);
			if (parts.length < 2 || parts[0].trim().isEmpty())
			{
				continue;
			}
			Character c = null;
			if (parts.length == 2 && parts[1].length() == 1)
			{
				c = parts[1].charAt(0);
			}
			else if (parts.length == 3)
			{
				try
				{
					int code = Integer.parseInt(parts[1]);
					int mods = Integer.parseInt(parts[2]);
					String text = KeyEvent.getKeyText(code);
					if (mods == 0 && text.length() == 1)
					{
						c = text.charAt(0);
					}
				}
				catch (NumberFormatException ignored)
				{
					// A damaged line is skipped
				}
			}
			// Each key belongs to one teleport only; a repeat (from an older save) is dropped
			if (c != null && isUsable(c) && !out.containsValue(Character.toLowerCase(c)))
			{
				out.put(parts[0].trim(), Character.toLowerCase(c));
			}
		}
		return out;
	}

	/** A key the game can match: a single visible character. */
	static boolean isUsable(char c)
	{
		return c != KeyEvent.CHAR_UNDEFINED && !Character.isISOControl(c) && !Character.isWhitespace(c);
	}

	Character get(Kind kind, String name)
	{
		return find(view(kind), name);
	}

	/** Binds the key to the teleport, taking it off any other teleport that had it. */
	private void set(Kind kind, String name, char key)
	{
		char k = Character.toLowerCase(key);
		Map<String, Character> map = all(kind);
		map.values().removeIf(v -> v == k);
		removeName(map, name);
		map.put(name.trim(), k);
		save(kind, map);
	}

	void reset(Kind kind, String name)
	{
		Map<String, Character> map = all(kind);
		removeName(map, name);
		save(kind, map);
	}

	private void save(Kind kind, Map<String, Character> map)
	{
		if (map.isEmpty())
		{
			configManager.unsetConfiguration(PohTeleportSorterConfig.GROUP, kind.key);
		}
		else
		{
			StringBuilder sb = new StringBuilder();
			for (Map.Entry<String, Character> e : map.entrySet())
			{
				if (sb.length() > 0)
				{
					sb.append('\n');
				}
				sb.append(e.getKey()).append('\t').append(e.getValue());
			}
			configManager.setConfiguration(PohTeleportSorterConfig.GROUP, kind.key, sb.toString());
		}
		pins.markChanged();
	}

	private static Character find(Map<String, Character> map, String name)
	{
		for (Map.Entry<String, Character> e : map.entrySet())
		{
			if (e.getKey().equalsIgnoreCase(name.trim()))
			{
				return e.getValue();
			}
		}
		return null;
	}

	private static void removeName(Map<String, Character> map, String name)
	{
		map.keySet().removeIf(k -> k.equalsIgnoreCase(name.trim()));
	}

	// ---------------------------------------------------------------- keys and labels

	/**
	 * The key a teleport answers to: its custom hotkey if it has one, otherwise the game's own key, unless another
	 * teleport's custom hotkey has taken that key. Upper case, as the game shows its letters; empty for no key.
	 */
	String effectiveKey(Kind kind, String name, String gameKey)
	{
		String game = gameKey == null ? "" : gameKey;
		Map<String, Character> map = view(kind);
		Character own = find(map, name);
		if (own != null)
		{
			return String.valueOf(own).toUpperCase();
		}
		if (game.length() == 1 && map.containsValue(Character.toLowerCase(game.charAt(0))))
		{
			return "";
		}
		return game;
	}

	/**
	 * The key to show next to a teleport: "Press a key" while one is being chosen for it, otherwise the key it
	 * answers to. With Better Teleport Menu on, the game's own key.
	 */
	String label(Kind kind, String name, String gameKey)
	{
		if (!isEnabled())
		{
			return gameKey == null ? "" : gameKey;
		}
		if (kind == captureKind && captureName != null && captureName.equalsIgnoreCase(name.trim()))
		{
			return PROMPT;
		}
		return effectiveKey(kind, name, gameKey);
	}

	/**
	 * Swaps the key at the front of the game's row text for another. The nexus writes rows as
	 * "<col=ffffff>C</col> :  Camelot" and the jewellery box as "<col=ccccff>1:</col> Ring of dueling"; rows past
	 * the game's 35 keys have no key at all. An empty key leaves just the name.
	 */
	static String relabel(Kind kind, String gameText, String key)
	{
		if (gameText == null)
		{
			return null;
		}
		String rest = gameText;
		String sep = kind == Kind.NEXUS ? "</col> :  " : "</col> ";
		String open = kind == Kind.NEXUS ? "<col=ffffff>" : "<col=ccccff>";
		if (gameText.startsWith(open))
		{
			int at = gameText.indexOf(sep);
			if (at > 0)
			{
				rest = gameText.substring(at + sep.length());
			}
		}
		if (key == null || key.isEmpty())
		{
			return rest;
		}
		return kind == Kind.NEXUS
			? open + key + sep + rest
			: open + key + ":" + sep + rest;
	}

	// ---------------------------------------------------------------- the game's listeners

	/**
	 * Changes arguments of one of the game's listeners, but only on a listener that is the expected game script
	 * with the expected shape. The version first seen is kept, so it can be put back exactly.
	 *
	 * @param values position in the listener's arguments, then the value to put there, repeated
	 * @return false if the listener isn't the expected one, in which case it is left alone
	 */
	boolean setArguments(Widget w, boolean keyListener, int scriptId, int length, Object... values)
	{
		if (w == null)
		{
			return false;
		}
		Object[] now = keyListener ? w.getOnKeyListener() : w.getOnOpListener();
		if (now == null || now.length != length || !Objects.equals(now[0], scriptId))
		{
			return false;
		}
		// Each changed argument must already be there with the same type (a string stays a string)
		for (int i = 0; i < values.length; i += 2)
		{
			int at = (Integer) values[i];
			if (now[at] == null || values[i + 1] == null || now[at].getClass() != values[i + 1].getClass())
			{
				return false;
			}
		}
		Object[] changed = now.clone();
		boolean differs = false;
		for (int i = 0; i < values.length; i += 2)
		{
			int at = (Integer) values[i];
			if (!Objects.equals(changed[at], values[i + 1]))
			{
				changed[at] = values[i + 1];
				differs = true;
			}
		}
		if (!differs)
		{
			return true;
		}
		(keyListener ? originalKeyListeners : originalOpListeners).putIfAbsent(w, now.clone());
		set(w, keyListener, changed);
		return true;
	}

	/**
	 * Gives a widget a key listener copied from another of the game's own, for a teleport the game gave no key
	 * (only its first 35 get one). The copy is removed again by {@link #restoreListeners()}.
	 */
	void addListener(Widget w, Object[] copy)
	{
		if (w == null || copy == null)
		{
			return;
		}
		originalKeyListeners.putIfAbsent(w, new Object[0]);
		w.setOnKeyListener(copy);
	}

	/** Puts every listener this plugin changed back as the game made it. Called on the client thread. */
	void restoreListeners()
	{
		for (Map.Entry<Widget, Object[]> e : originalKeyListeners.entrySet())
		{
			set(e.getKey(), true, e.getValue().length == 0 ? null : e.getValue());
		}
		for (Map.Entry<Widget, Object[]> e : originalOpListeners.entrySet())
		{
			set(e.getKey(), false, e.getValue());
		}
		forgetListeners();
	}

	private void forgetListeners()
	{
		originalKeyListeners.clear();
		originalOpListeners.clear();
	}

	private static void set(Widget w, boolean keyListener, Object[] args)
	{
		if (keyListener)
		{
			w.setOnKeyListener(args);
		}
		else
		{
			w.setOnOpListener(args);
		}
	}

	/** Whether a listener is the expected game script with the expected number of arguments. */
	static boolean isExpectedShape(Object[] args, int scriptId, int length)
	{
		return args != null && args.length == length && Objects.equals(args[0], scriptId);
	}

	/** The listener's characters for a key: upper case, then lower case (empty when the same, as the game does). */
	static String[] characters(String key)
	{
		String upper = key == null ? "" : key.toUpperCase();
		String lower = key == null ? "" : key.toLowerCase();
		return new String[]{upper, lower.equals(upper) ? "" : lower};
	}

	// ---------------------------------------------------------------- choosing a key

	/** Starts waiting for the key to bind to this teleport. Called on the client thread. */
	void startCapture(Kind kind, String name)
	{
		captureKind = kind;
		captureName = name.trim();
		runRedraw();
	}

	private void finishCapture(Character key)
	{
		Kind kind = captureKind;
		String name = captureName;
		captureKind = null;
		captureName = null;
		if (kind != null && name != null && key != null)
		{
			set(kind, name, key);
		}
		clientThread.invoke(this::runRedraw);
	}

	private void runRedraw()
	{
		Runnable r = redraw;
		if (r != null)
		{
			r.run();
		}
	}

	/**
	 * While a hotkey is being chosen, the next key is taken for it: Esc cancels, a letter, number or symbol is
	 * chosen, and anything else (Ctrl or Alt combinations, F-keys, arrows) is ignored while waiting for another.
	 * The choice is made from the typed character, as the game matches it, so Shift+1 chooses "!".
	 */
	@Override
	public void keyPressed(KeyEvent e)
	{
		swallowTyped = false;
		if (captureKind == null)
		{
			return;
		}
		if (e.getKeyCode() == KeyEvent.VK_SHIFT)
		{
			return;
		}
		e.consume();
		if (e.getKeyCode() == KeyEvent.VK_ESCAPE)
		{
			swallowTyped = true;
			finishCapture(null);
			return;
		}
		int mods = e.getModifiersEx() & (InputEvent.CTRL_DOWN_MASK | InputEvent.ALT_DOWN_MASK | InputEvent.META_DOWN_MASK);
		char c = e.getKeyChar();
		if (mods != 0 || !isUsable(c))
		{
			// A key the game can't match: keep waiting
			return;
		}
		swallowTyped = true;
		finishCapture(c);
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		if (swallowTyped || captureKind != null)
		{
			e.consume();
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		if (swallowTyped)
		{
			e.consume();
			swallowTyped = false;
		}
	}

	@Override
	public void focusLost()
	{
		swallowTyped = false;
	}

	private boolean isOpen(Kind kind)
	{
		return kind == Kind.NEXUS
			? client.getWidget(InterfaceID.TelenexusTeleport.CONTENT) != null
			: client.getWidget(InterfaceID.PohJewelleryBox.UNIVERSE) != null;
	}
}

package com.pohteleportsorter;

import java.awt.event.KeyEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;
import net.runelite.client.util.Text;

/**
 * The search field shown in the title bar of the Portal Nexus and the jewellery box, left of the title.
 *
 * While the field is being typed in, every key goes to it: the key is consumed, so the window's own
 * hotkeys don't fire, and neither do the shortcuts of any plugin whose key listener runs after this one.
 *
 * Better Teleport Menu runs these windows' hotkeys itself, from its own key listener. RuneLite gives keys
 * to listeners in the order their plugins started, which can't be controlled, so it could see the keys
 * typed into the search first and teleport. The search is therefore left out while that plugin is on.
 *
 * Enter finishes typing but keeps the results, so the next key press is a normal hotkey again; Esc clears
 * the search; Ctrl+A selects the whole search, so the next key replaces it and Backspace or Delete clears
 * it. Only one of the two windows can be open at a time, so one field is shared between them.
 */
@Singleton
public class TeleportSearch implements KeyListener
{
	/** Where the field goes: the title bar's clear band (top to bottom) and its left inner edge. */
	static final class Band
	{
		final int top;
		final int bottom;
		final int left;

		Band(int top, int bottom, int left)
		{
			this.top = top;
			this.bottom = bottom;
			this.left = left;
		}
	}

	private static final int HEIGHT = 20;
	private static final int MAX_WIDTH = 170;
	private static final int MIN_WIDTH = 100;
	// Equal space either side of the field: from the border's inner edge, and before the title text
	private static final int SIDE_GAP = 12;
	private static final int MAX_LENGTH = 24;

	private static final int TEXT_COLOUR = 0xffffff;
	private static final int HINT_COLOUR = 0x9f9f9f;
	private static final int CLEAR_COLOUR = 0xff981f;
	private static final int HOVER_COLOUR = 0xffffff;
	private static final int THINBOX_OUTER = 0x0e0e0c;
	private static final int THINBOX_INNER = 0x474745;
	// The same selection colour as RuneLite's own chatbox text input
	private static final int SELECTION_COLOUR = 0x113399;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private BetterTeleportMenu betterTeleportMenu;

	// Written on the AWT thread by the key dispatcher, read on the client thread
	private volatile boolean typing;
	private volatile boolean allSelected;
	private volatile String query = "";
	// The key that ended typing (Enter/Esc): its remaining typed/released events are swallowed too
	private volatile int swallowKeyCode = -1;

	private int rootId = -1;
	private Runnable onChange;
	private Widget text;
	private Widget selection;
	private Widget clear;
	private int textX;
	private int textY;
	private final java.util.List<Widget> widgets = new java.util.ArrayList<>();

	/**
	 * Shows the field in a window's title bar: centred vertically in the bar's clear band, and centred
	 * horizontally in the space between the border and the title text. {@code frame} is the layer holding
	 * the window's border and title (the title is its child 1). {@code onChange} re-filters the window.
	 */
	void attach(Widget root, Widget frame, Band band, Runnable onChange)
	{
		typing = false;
		allSelected = false;
		query = "";
		this.rootId = root.getId();
		this.onChange = onChange;

		int span = titleLeft(frame) - band.left;
		int width = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, span - SIDE_GAP * 2));
		int x = band.left + Math.max(SIDE_GAP / 2, (span - width) / 2);
		int y = band.top + (band.bottom - band.top - HEIGHT) / 2;

		Widget bg = root.createChild(-1, WidgetType.GRAPHIC);
		bg.setSpriteId(SpriteID.TRADEBACKING_DARK);
		bg.setSpriteTiling(true);
		place(bg, x + 1, y + 1, width - 2, HEIGHT - 2);

		Widget outer = root.createChild(-1, WidgetType.RECTANGLE);
		outer.setFilled(false);
		outer.setTextColor(THINBOX_OUTER);
		place(outer, x, y, width, HEIGHT);

		Widget inner = root.createChild(-1, WidgetType.RECTANGLE);
		inner.setFilled(false);
		inner.setTextColor(THINBOX_INNER);
		place(inner, x + 1, y + 1, width - 2, HEIGHT - 2);

		// Drawn under the text, sized to it when everything is selected
		textX = x + 5;
		textY = y;
		selection = root.createChild(-1, WidgetType.RECTANGLE);
		selection.setFilled(true);
		selection.setTextColor(SELECTION_COLOUR);
		place(selection, textX - 1, y + 4, 1, HEIGHT - 8);
		selection.setHidden(true);

		text = root.createChild(-1, WidgetType.TEXT);
		text.setFontId(FontID.PLAIN_11);
		text.setTextShadowed(true);
		text.setXTextAlignment(WidgetTextAlignment.LEFT);
		text.setYTextAlignment(WidgetTextAlignment.CENTER);
		place(text, textX, y, width - 20, HEIGHT);
		text.setHasListener(true);
		text.setAction(0, "Search");
		text.setName("");
		text.setOnOpListener((JavaScriptCallback) ev -> startTyping());

		clear = root.createChild(-1, WidgetType.TEXT);
		clear.setFontId(FontID.PLAIN_11);
		clear.setTextShadowed(true);
		clear.setTextColor(CLEAR_COLOUR);
		clear.setXTextAlignment(WidgetTextAlignment.CENTER);
		clear.setYTextAlignment(WidgetTextAlignment.CENTER);
		clear.setText("x");
		place(clear, x + width - 15, y, 12, HEIGHT);
		clear.setHasListener(true);
		clear.setAction(0, "Clear");
		clear.setName("<col=ff9040>Search</col>");
		clear.setOnOpListener((JavaScriptCallback) ev -> clearSearch());
		clear.setOnMouseOverListener((JavaScriptCallback) ev -> clear.setTextColor(HOVER_COLOUR));
		clear.setOnMouseLeaveListener((JavaScriptCallback) ev -> clear.setTextColor(CLEAR_COLOUR));

		widgets.clear();
		for (Widget w : new Widget[]{bg, outer, inner, selection, text, clear})
		{
			w.revalidate();
			widgets.add(w);
		}
		refresh();
	}

	/** Left edge of the title's text, worked out from its font, as the game centres it in its box. */
	private static int titleLeft(Widget frame)
	{
		Widget title = frame != null ? frame.getChild(1) : null;
		if (title == null || title.getFont() == null || title.getText() == null)
		{
			return MIN_WIDTH + SIDE_GAP * 2 + 26;
		}
		int textW = title.getFont().getTextWidth(Text.removeTags(title.getText()));
		return title.getRelativeX() + (title.getWidth() - textW) / 2;
	}

	/** Ends the search. When the window is still open (plugin turned off), the field is hidden too. */
	void detach()
	{
		swallowKeyCode = -1;
		if (rootId != -1 && client.getWidget(rootId) != null)
		{
			for (Widget w : widgets)
			{
				w.setHidden(true);
				w.setHasListener(false);
			}
		}
		widgets.clear();
		typing = false;
		allSelected = false;
		query = "";
		rootId = -1;
		onChange = null;
		text = null;
		selection = null;
		clear = null;
	}

	/** The search text, lower case and trimmed; empty when not searching. */
	String query()
	{
		return query.trim().toLowerCase();
	}

	boolean matches(String... fields)
	{
		String q = query();
		if (q.isEmpty())
		{
			return true;
		}
		for (String f : fields)
		{
			if (f != null && f.toLowerCase().contains(q))
			{
				return true;
			}
		}
		return false;
	}

	/** Called when a teleport is clicked: typing ends, results stay. */
	void stopTyping()
	{
		if (typing)
		{
			typing = false;
			allSelected = false;
			refresh();
		}
	}

	private void startTyping()
	{
		typing = true;
		allSelected = false;
		refresh();
	}

	private void clearSearch()
	{
		typing = false;
		allSelected = false;
		query = "";
		changed();
	}

	private void changed()
	{
		refresh();
		if (onChange != null)
		{
			onChange.run();
		}
	}

	private void refresh()
	{
		if (text == null)
		{
			return;
		}
		String q = query;
		boolean selected = typing && allSelected && !q.isEmpty();
		if (selected)
		{
			text.setText(Text.escapeJagex(q));
			text.setTextColor(TEXT_COLOUR);
		}
		else if (typing)
		{
			text.setText(Text.escapeJagex(q) + "|");
			text.setTextColor(TEXT_COLOUR);
		}
		else if (q.isEmpty())
		{
			text.setText("Search");
			text.setTextColor(HINT_COLOUR);
		}
		else
		{
			text.setText(Text.escapeJagex(q));
			text.setTextColor(TEXT_COLOUR);
		}

		if (selection != null)
		{
			FontTypeFace font = text.getFont();
			int w = font != null ? font.getTextWidth(q) : q.length() * 6;
			selection.setOriginalX(textX - 1);
			selection.setOriginalY(textY + 4);
			selection.setOriginalWidth(w + 2);
			selection.setHidden(!selected);
			selection.revalidate();
		}
		if (clear != null)
		{
			clear.setHidden(q.isEmpty());
		}
	}

	/** Ends the search when its window closes. */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (rootId != -1 && client.getWidget(rootId) == null)
		{
			detach();
		}
	}

	/**
	 * Whether the search field can be shown: not while Better Teleport Menu is on, since its hotkeys could
	 * fire while typing. Checked each time a window opens.
	 */
	boolean isAvailable()
	{
		return !betterTeleportMenu.isActive();
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		take(e);
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		take(e);
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		take(e);
	}

	/** Consumes the key, so the game and later listeners never see it, if it belongs to the search. */
	private void take(KeyEvent e)
	{
		if (handle(e))
		{
			e.consume();
		}
	}

	/** Returns true if the key belongs to the search field. */
	private boolean handle(KeyEvent e)
	{
		int code = e.getKeyCode();
		if (!typing)
		{
			// Swallow what's left of the key that ended typing, so an Enter can't fall through to the chatbox
			if (swallowKeyCode != -1)
			{
				if (e.getID() == KeyEvent.KEY_RELEASED && code == swallowKeyCode)
				{
					swallowKeyCode = -1;
					return true;
				}
				if (e.getID() == KeyEvent.KEY_TYPED)
				{
					return true;
				}
			}
			return false;
		}

		switch (e.getID())
		{
			case KeyEvent.KEY_PRESSED:
				if (code == KeyEvent.VK_A && e.isControlDown() && !e.isAltDown())
				{
					allSelected = !query.isEmpty();
					clientThread.invoke(this::refresh);
				}
				else if (code == KeyEvent.VK_ENTER)
				{
					// Keep the results; the next key press is a normal hotkey again
					typing = false;
					allSelected = false;
					swallowKeyCode = code;
					clientThread.invoke(this::refresh);
				}
				else if (code == KeyEvent.VK_ESCAPE)
				{
					typing = false;
					allSelected = false;
					query = "";
					swallowKeyCode = code;
					clientThread.invoke(this::changed);
				}
				else if (code == KeyEvent.VK_BACK_SPACE || code == KeyEvent.VK_DELETE)
				{
					if (allSelected)
					{
						allSelected = false;
						query = "";
						clientThread.invoke(this::changed);
					}
					else if (code == KeyEvent.VK_BACK_SPACE && !query.isEmpty())
					{
						query = query.substring(0, query.length() - 1);
						clientThread.invoke(this::changed);
					}
				}
				else if (allSelected && isNavigationKey(code))
				{
					// Arrow keys, Home and End drop the selection, as in any text box
					allSelected = false;
					clientThread.invoke(this::refresh);
				}
				break;
			case KeyEvent.KEY_TYPED:
			{
				char c = e.getKeyChar();
				if (c != KeyEvent.CHAR_UNDEFINED && !Character.isISOControl(c))
				{
					if (allSelected)
					{
						// Typing over a selection replaces it
						allSelected = false;
						query = String.valueOf(c);
						clientThread.invoke(this::changed);
					}
					else if (query.length() < MAX_LENGTH)
					{
						query = query + c;
						clientThread.invoke(this::changed);
					}
				}
				break;
			}
			default:
				break;
		}
		// While typing, every key belongs to the search field
		return true;
	}

	private static boolean isNavigationKey(int code)
	{
		switch (code)
		{
			case KeyEvent.VK_LEFT:
			case KeyEvent.VK_RIGHT:
			case KeyEvent.VK_UP:
			case KeyEvent.VK_DOWN:
			case KeyEvent.VK_HOME:
			case KeyEvent.VK_END:
				return true;
			default:
				return false;
		}
	}

	private static void place(Widget w, int x, int y, int width, int height)
	{
		w.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
		w.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		w.setWidthMode(WidgetSizeMode.ABSOLUTE);
		w.setHeightMode(WidgetSizeMode.ABSOLUTE);
		w.setOriginalX(x);
		w.setOriginalY(y);
		w.setOriginalWidth(width);
		w.setOriginalHeight(height);
	}
}

package com.pohteleportsorter;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;

/**
 * Makes a window's title bar a little taller, so the search field has room around it, and puts every
 * widget it moved back exactly where the game had it.
 *
 * The title bars are drawn by the game's stoneborder (Portal Nexus) and steelborder (jewellery box)
 * scripts as children of the window's frame layer: child 1 is the title text, the divider under the bar
 * follows the border pieces, and the close button comes after it.
 */
final class TitleBar
{
	/** How much taller the title bar gets, in interface pixels. */
	static final int EXTRA = 6;

	private static final class Saved
	{
		final Widget widget;
		final int y;
		final int height;

		Saved(Widget widget)
		{
			this.widget = widget;
			this.y = widget.getOriginalY();
			this.height = widget.getOriginalHeight();
		}
	}

	private final List<Saved> saved = new ArrayList<>();

	/** Moves a widget down. Missing widgets (a window without a close button, say) are skipped. */
	void moveDown(Widget w, int dy)
	{
		if (w == null)
		{
			return;
		}
		saved.add(new Saved(w));
		w.setOriginalY(w.getOriginalY() + dy);
		w.revalidate();
	}

	/**
	 * Moves the top of a layer down while keeping its bottom where it was. Works for layers sized
	 * "parent minus N" (it adds to N) and for fixed-height layers (it takes from the height).
	 */
	void moveTopDown(Widget w, int dy)
	{
		if (w == null)
		{
			return;
		}
		saved.add(new Saved(w));
		w.setOriginalY(w.getOriginalY() + dy);
		if (w.getHeightMode() == WidgetSizeMode.MINUS)
		{
			w.setOriginalHeight(w.getOriginalHeight() + dy);
		}
		else
		{
			w.setOriginalHeight(Math.max(0, w.getOriginalHeight() - dy));
		}
		w.revalidate();
	}

	boolean isExtended()
	{
		return !saved.isEmpty();
	}

	/** Puts everything back as the game drew it. */
	void restore()
	{
		for (int i = saved.size() - 1; i >= 0; i--)
		{
			Saved s = saved.get(i);
			s.widget.setOriginalY(s.y);
			s.widget.setOriginalHeight(s.height);
			s.widget.revalidate();
		}
		saved.clear();
	}

	/** Forgets what was moved, for when the window has closed and its widgets are gone. */
	void forget()
	{
		saved.clear();
	}
}

package com.pohteleportsorter;

/** Optional styling for teleports that land in the Wilderness. Display only. */
final class WildStyle
{
	private static final String RED = "<col=ff0000>";

	private WildStyle()
	{
	}

	/**
	 * Styles a row's text. {@code name} is the destination name as it appears in {@code text};
	 * highlight turns that name red, asterisk adds a red * after it.
	 */
	static String apply(String text, String name, boolean wild, boolean asterisk, boolean highlight)
	{
		if (!wild || text == null || name == null || name.isEmpty())
		{
			return text;
		}
		String out = text;
		if (highlight)
		{
			int at = out.lastIndexOf(name);
			if (at >= 0)
			{
				out = out.substring(0, at) + RED + name + "</col>" + out.substring(at + name.length());
			}
		}
		if (asterisk)
		{
			out = out + RED + "*</col>";
		}
		return out;
	}
}

